let profile=read('blokko-profile',null),records=read('seyyah-records',[]),stage=Math.min(LEVELS.length,Math.max(1,Math.floor(Number(read('seyyah-stage',1))||1))),page='home',puzzleController=null,sound=read('blokko-sound',true),onlineRequest=0;
