function render(){onlineRequest++;communityCleanup?.();communityCleanup=null;if(puzzleController){puzzleController.destroy();puzzleController=null;}document.querySelector('#app').innerHTML=`<div class="app-shell"><aside class="desktop-nav"><a class="brand" href="#" id="brand-link"><span class="seyyah-logo">${icon('compass')}</span><span class="brand-name">kelime<br><b>seyyahı</b></span></a><span class="nav-label">KELİMELERİN PEŞİNDE</span><nav>${nav()}</nav><div class="desktop-note">Bir harf.<br>Bir kelime.<br><b>Yeni bir dünya.</b><span>✦</span></div></aside><div class="app-content"><header class="app-header"><div class="mobile-brand">${icon('compass')}<span>kelime <b>seyyahı</b></span></div><span class="header-label">HER KELİME YENİ BİR YOLCULUK.</span><div class="header-actions"><span class="gold-chip" id="gold-balance">${icon('coins')} ${wallet.gold}</span><span class="stage-chip">${icon('map-pin')} Aşama ${stage}</span><button class="icon-btn" id="sound" aria-label="Sesi aç veya kapat">${icon(sound?'volume-2':'volume-x')}</button></div></header><div id="account-sync-state" class="sync-banner" role="status"></div><div id="page"></div><footer>Merakını takip et. Kelimeler yol göstersin. ✦</footer></div><nav class="bottom-nav" aria-label="Ana menü">${nav()}</nav></div><div id="modal-root"></div><div id="toast" role="status"></div>`;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0);});document.querySelector('#brand-link').onclick=e=>{e.preventDefault();page='home';render();};document.querySelector('#sound').onclick=()=>{sound=!sound;save('blokko-sound',sound);document.querySelector('#sound').innerHTML=icon(sound?'volume-2':'volume-x');refresh();};
 if(page==='news')document.querySelector('#page').innerHTML=announcementsPage(livePolicy(),serverClock.now());if(page==='journey')showJourney();if(page==='home')home();if(page==='profile')profilePage();if(page==='ranks')ranksPage();if(page==='shop')shopPage();if(page==='community')communityCleanup=mountCommunity({profile,showLogin,showLegal,hasConsent,icon,refresh,toast});refresh();updateAccountStatus();}
function home(){const current=LEVELS[stage-1],completed=Object.values(progress).filter(p=>p.completed).length,start=Math.max(1,stage-2),allDone=completed===LEVELS.length;
 document.querySelector('#page').innerHTML=`<section class="home-intro"><div class="eyebrow">KELİMELERLE BİR YOLCULUK</div><h1>Bir kelime bul.<br><span>Yeni bir yer keşfet.</span></h1><p>Zihnini dinlendir, merakını takip et. Yolculuğun seni bekliyor.</p></section><section class="journey-hero word-hero">${landscape(current.regionIndex)}<div class="journey-copy"><span class="hero-tag">${allDone?'HARİKA BİR YOLCULUKTU':'SIRADAKİ DURAĞIN'}</span><h2>${current.region.name}</h2><p>${current.region.subtitle}<br>Aşama ${stage} · ${current.words.length} kelime</p><button class="primary" id="continue">${icon('compass')} ${allDone?'Yeniden keşfet':'Yolculuğa devam et'} →</button></div><span class="hero-postmark">KELİME<br><b>SEYYAHI</b><small>✦ KEŞFET ✦</small></span></section><div class="home-stats"><div>${icon('book-open')}<span>TAMAMLANAN<strong>${completed} / ${LEVELS.length}</strong></span></div><div>${icon('trophy')}<span>KUPALARIN<strong>${cups().toLocaleString('tr')}</strong></span></div><div>${icon('map-pin')}<span>BULUNDUĞUN AŞAMA<strong>${stage}</strong></span></div></div>${newsBanner(livePolicy(),serverClock.now())}${journeyTeaser(journey,playDate())}${streakCard()}<button class="shop-banner" id="open-shop"><span>${icon('lightbulb')} <b>${wallet.hints} ipucu</b> · Yolunu aydınlat</span><span>Mağazayı keşfet →</span></button><section class="stage-section"><div class="section-heading"><div><span class="eyebrow">KÜÇÜK ADIMLAR, GÜZEL KEŞİFLER</span><h2>Yol haritan</h2></div><span class="pill">${LEVELS.length} özgün bulmaca</span></div><div class="stage-grid">${LEVELS.slice(start-1,start+5).map(l=>`<button class="stage-tile ${progress[l.id]?.completed?'stage-done':l.id===stage?'stage-current':'stage-locked'}" data-stage="${l.id}" ${l.id>stage?'disabled':''}><span>${progress[l.id]?.completed?'✓':l.id===stage?'BURADASIN':icon('lock')}</span><strong>${l.id}</strong><small>${l.region.name}</small>${l.id===stage?icon('chevron-right'):''}</button>`).join('')}</div><div class="destination-list">${REGIONS.map((r,i)=>`<button class="destination ${regionLevels(i)[0].id<=stage?'':'locked'}" data-destination="${regionLevels(i)[0].id}" ${regionLevels(i)[0].id>stage?'disabled':''}><span>${icon(regionLevels(i)[0].id<=stage?'map-pin':'lock')}</span><div><b>${r.name}</b><small>Aşama ${regionLevels(i)[0].id}–${regionLevels(i).at(-1).id} · ${regionLevels(i).filter(l=>progress[l.id]?.completed).length}/${regionLevels(i).length} tamamlandı</small></div>${icon('chevron-right')}</button>`).join('')}</div><p class="stage-note">Bulmacayı tamamla, sonraki durağı aç. Bir hesapla giriş yaptıysan ilerlemen buluta eşitlenir; durumu Profil’den kontrol et.</p></section><section class="how-card">${icon('compass')}<div><h3>Birleştir, bul, keşfet.</h3><p>Dairedeki harfleri parmağınla birleştir. Bulduğun kelimeler bulmacayı doldursun.</p></div></section>`;
 document.querySelector('#open-news')?.addEventListener('click',()=>{page='news';render();window.scrollTo(0,0);});document.querySelector('#open-journey').onclick=()=>{page='journey';render();window.scrollTo(0,0);};document.querySelector('#streak-practice').onclick=()=>play(stage);document.querySelector('#open-shop').onclick=()=>{page='shop';render();};document.querySelector('#continue').onclick=()=>play(stage);document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>play(+b.dataset.stage));document.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>play(+b.dataset.destination));}
function updateWalletUI(){const el=document.querySelector('#gold-balance');if(el){el.innerHTML=icon('coins')+' '+wallet.gold;refresh();}}
function gameAllowed(){return canPlay()&&!rewardBusy;}
function play(n){if(!gameAllowed()){toast('Devam etmek için bağlantıyı ve Profil’deki hesap eşitlemesini kontrol et.');refreshAccessUI();return;}if(!trophyNoticeSeen()){showTrophyNotice();return;}if(!hasConsent()){showLegal(true);return;}const level=LEVELS[n-1];if(!level||n>stage)return;if(puzzleController){puzzleController.destroy();puzzleController=null;}document.querySelector('#page').innerHTML='<div class="word-game"></div>';
 const old=progress[n]||{};
 puzzleController=mountWordGame(document.querySelector('.word-game'),{level,saved:old.completed?{}:old,onSound:beep,onLetterSound:playLetterSound,hintLabel:()=>wallet.hints>0?wallet.hints+' hazır ipucu':'20 altın',canInteract:gameAllowed,onSave:state=>{progress[n]={...state,completed:!!progress[n]?.completed};save('seyyah-progress',progress);},onHint:()=>{if(!gameAllowed())return false;const result=spendHint(read('seyyah-wallet',{}));if(!result.ok)return false;wallet=result.wallet;save('seyyah-wallet',wallet);updateWalletUI();return true;},onComplete:r=>{if(!gameAllowed())return {gold:0,cups:0};
 journey=recordJourney(journey,{levelId:n,hints:r.hints},playDate());save('seyyah-journey',journey);save(streakKey(),recordPractice(read(streakKey(),{}),playDate()));const premiumBonus=hasPremium()&&!bonusUnconfirmed&&!trophies.claimed.includes(n);const reward=awardPuzzle(read('seyyah-wallet',{}),level,premiumBonus);wallet=reward.wallet;save('seyyah-wallet',wallet);progress[n]={...progress[n],completed:true};save('seyyah-progress',progress);stage=Math.min(LEVELS.length,Math.max(stage,n+1));save('seyyah-stage',stage);const trophyReward=awardTrophies(trophies,n,!!profile&&!profile.guest&&canUseServices()&&!bonusUnconfirmed&&!!activeHoliday(livePolicy(),serverClock.now()),premiumBonus);trophies=trophyReward.trophies;save('seyyah-trophies',trophies);if(trophyReward.earned>20){rewardBusy=true;refreshAccessUI();syncAccountNow().then(()=>{bonusUnconfirmed=accountSync.dirty;if(!accountSync.dirty)toast('Bölüm kaydı ve onaylanan ek ödüller hesabına işlendi.');else toast('Ek ödüller henüz doğrulanmadı; Profil’den eşitle.');}).finally(()=>{rewardBusy=false;refreshAccessUI();});}updateWalletUI();const chip=document.querySelector('.stage-chip');if(chip){chip.innerHTML=icon('map-pin')+' Aşama '+stage;refresh();}sendActivity();return {gold:premiumBonus?reward.earned/2:reward.earned,cups:trophyReward.earned>20?20:trophyReward.earned,pending:trophyReward.earned>20,quest:journey.start&&!journey.claimed.includes(journey.active)?'Keşif defteri · Gün '+journey.active+': '+questProgress(journey,journey.active)+' / '+QUESTS[journey.active-1].target:null};
 },onJourney:()=>{page='journey';render();window.scrollTo(0,0);},onNext:()=>{if(n<LEVELS.length)play(n+1);else render();window.scrollTo(0,0);},onHome:()=>render()});refresh();window.scrollTo(0,0);}
function profilePage(){document.querySelector('#page').innerHTML=`<section class="page-title"><div class="eyebrow">SENİN OYUN ALANIN</div><h1>Profilim</h1><p>Her kelimede yeni bir keşif.</p></section><section class="profile-card"><span class="large-avatar avatar-portrait">${avatarSVG(avatar)}</span><h2>${escape(profile?.name||'Misafir oyuncu')}</h2><span class="pill">${accountLabel(profile)}</span>${profile&&!profile.guest?`<p class="uid-label">Oyuncu UID: <code>${escape(profile.uid)}</code><button class="text-link" id="copy-uid">UID’yi kopyala</button></p>`:''}<button class="text-link" id="edit-avatar">Avatarını düzenle</button><div class="profile-metrics"><div><strong>${stage}</strong><span>Aşama</span></div><div><strong>${cups()}</strong><span>Kupa</span></div><div><strong>${trophies.prestige}</strong><span class="prestige-red">Prestij</span></div></div><button class="primary" id="account">${profile&&!profile.guest?'Çıkış yap':'Google / GitHub / Yahoo ile giriş yap'}</button><p id="account-error" role="status"></p><div class="profile-links"><a href="mailto:${SUPPORT}">Destek için<br><strong>${SUPPORT}</strong></a><button id="legal-link">Kullanım Koşulları ve Gizlilik Politikası</button><span>Sürüm ${APP_VERSION}</span><p id="version-status">${escape(updateState.message)}</p><button id="check-version">Güncellemeleri kontrol et</button><button id="profile-update" class="primary ${updateState.status==='update'?'':'hidden'}">GitHub’dan indir</button></div><p class="stage-note">Aynı giriş hesabıyla başka cihazda ilerlemeni geri yükleyebilirsin. Önce bu cihazda “Hesabına kaydedildi” durumunu gör. Misafir kayıtları cihazda kalır.</p></section>`;document.querySelector('#page').insertAdjacentHTML('beforeend',accountPanel()+newsBanner(livePolicy(),serverClock.now())+journeyTeaser(journey,playDate())+avatarPanel()+badgesPanel(captureAccount())+streakCard(false)+notificationSettings());document.querySelector('#open-journey').onclick=()=>{page='journey';render();window.scrollTo(0,0);};document.querySelector('#open-news').onclick=()=>{page='news';render();};bindNotificationSettings();bindAvatar();updateAccountStatus();document.querySelector('#copy-uid')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(profile.uid);toast('UID kopyalandı.');}catch{toast('UID’yi ekrandan seçip kopyalayabilirsin.');}});document.querySelector('#legal-link').onclick=()=>showLegal(false);document.querySelector('#profile-update').onclick=()=>openUpdate();document.querySelector('#check-version').onclick=async()=>{const b=document.querySelector('#check-version'),el=document.querySelector('#version-status');b.disabled=true;el.textContent='GitHub kontrol ediliyor…';updateState=await checkUpdate();if(el.isConnected){el.textContent=updateState.message;b.disabled=false;document.querySelector('#profile-update').classList.toggle('hidden',updateState.status!=='update');}};document.querySelector('#account').onclick=async()=>{if(rewardBusy||accountSync.busy){toast('Hesap eşitlemesinin bitmesini bekle.');return;}if(notificationBusy){toast('Bildirim ayarının tamamlanmasını bekle.');return;}if(profile&&!profile.guest){try{if(accountSync.dirty){await syncAccountNow();if(accountSync.dirty&&!confirm('Henüz buluta kaydedilmemiş ilerleme var. Bu cihazda korunacak; yine de çıkış yapılsın mı?'))return;}await disconnectNotifications();servicesUid=null;await logout();resetAccess();profile=null;save('blokko-profile',null);switchAccount(null);render();}catch{document.querySelector('#account-error').textContent='Çıkış yapılamadı. Tekrar dene.';}}else showLogin();};}
function ranksPage(){const unlocked=cups()>=1000||trophies.prestige>0;document.querySelector('#page').innerHTML=`<section class="page-title"><div class="eyebrow">KUPALARIN PEŞİNDE</div><h1>Sıralama</h1><p>Her aşamanın ilk tamamlanmasına 20 kupa.</p></section><section class="ranking-card"><div class="ranking-tabs"><button class="active" id="world">Kupa sıralaması</button>${unlocked?'<button class="prestige-red" id="prestige-tab">Prestij</button>':''}</div><p>Kupaların: <b>${cups()}</b> · <b class="prestige-red">Prestij ${trophies.prestige}</b></p>${cups()>=1000?'<button class="primary prestige-action" id="prestige-up">1000 kupa harca · Prestij +1</button>':trophies.prestige===0?'<p class="stage-note">Prestij sekmesi 1000 kupada açılır. Aşamaların ve altının korunur.</p>':''}<div id="ranking-list" role="status" aria-live="polite"></div><p class="stage-note">Sunucuya eşitlenmiş hesaplar gösterilir. Eski puanlar bu sıralamaya dahil değildir. Kupa, aşama başına yalnızca bir kez kazanılır; prestij yapmak bu hakkı yenilemez. Standart ${LEVELS.length} aşamadan ${LEVELS.length*20} kupa kazanılabilir. Sunucuda onaylanan Bayram Bereketi ek kupaları ayrıca korunur.</p><button class="text-link" id="ranking-refresh">Yenile</button></section>`;
 let prestige=false;async function load(){const request=++onlineRequest,el=document.getElementById('ranking-list');el.textContent='Sıralama yükleniyor…';try{const rows=await getTrophyRanking(prestige);if(request!==onlineRequest||!el.isConnected)return;el.innerHTML=rows.length?rows.map((r,i)=>`<div class="score-entry ${prestige?'prestige-red':''}"><span class="score-position">${i+1}</span><span class="rank-avatar">${avatarSVG(r.avatar)}</span><span class="score-player">${escape(r.name)}<small>${prestige?r.trophies+' kupa':'Prestij '+r.prestige}</small></span><strong>${prestige?'Prestij '+r.prestige:r.trophies+' 🏆'}</strong></div>`).join(''):'<p class="community-empty">Henüz kayıt yok. Profil’den hesabını eşitleyerek katıl.</p>';}catch(e){if(request===onlineRequest&&el.isConnected)el.textContent=describeCloudError(e);}}
 document.getElementById('world').onclick=()=>{prestige=false;document.querySelectorAll('.ranking-tabs button').forEach(b=>b.classList.toggle('active',b.id==='world'));load();};document.getElementById('prestige-tab')?.addEventListener('click',()=>{prestige=true;document.querySelectorAll('.ranking-tabs button').forEach(b=>b.classList.toggle('active',b.id==='prestige-tab'));load();});document.getElementById('ranking-refresh').onclick=load;document.getElementById('prestige-up')?.addEventListener('click',()=>{if(!canPlay()||rewardBusy||accountView.kind==='loading'){toast('Çevrimiçi eşitlemenin bitmesini bekle.');return;}if(!confirm('1000 kupa harcanıp prestijin 1 artırılsın mı? Aşamaların korunur; aynı aşamalardan yeniden kupa kazanamazsın.'))return;const result=prestigeUp(trophies);if(result.ok){trophies=result.trophies;save('seyyah-trophies',trophies);render();toast('Prestijin yükseldi!');}});load();}

function showLogin(){document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Hesabınla giriş"><button class="modal-close icon-btn" id="close-login" aria-label="Kapat">×</button><div class="login-art travel-letters"><span>K</span><span>E</span><span>Ş</span><span>İ</span><span>F</span></div><h2>Kelime Seyyahı’na hoş geldin!</h2><p>Hesabınla giriş yap ya da misafir olarak maceraya başla.</p><button class="google-button" id="google"><svg viewBox="0 0 48 48" aria-hidden="true" focusable="false"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5Z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6C44.4 38.03 46.98 31.87 46.98 24.55Z"/><path fill="#FBBC05" d="M10.53 28.59A14.4 14.4 0 0 1 9.75 24c0-1.59.27-3.13.78-4.59l-7.98-6.19A23.87 23.87 0 0 0 0 24c0 3.87.93 7.52 2.56 10.78l7.97-6.19Z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.91-5.8l-7.73-6c-2.15 1.45-4.92 2.3-8.18 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48Z"/></svg> Google ile giriş yap</button><button class="github-button" id="github"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 .5a12 12 0 0 0-3.79 23.39c.6.11.82-.26.82-.58v-2.23c-3.34.73-4.04-1.42-4.04-1.42-.55-1.39-1.34-1.76-1.34-1.76-1.09-.75.09-.73.09-.73 1.21.09 1.84 1.24 1.84 1.24 1.07 1.83 2.81 1.3 3.49.99.11-.78.42-1.3.76-1.6-2.66-.3-5.47-1.33-5.47-5.93 0-1.31.47-2.38 1.24-3.22-.12-.3-.54-1.52.12-3.18 0 0 1.01-.32 3.3 1.23a11.52 11.52 0 0 1 6 0c2.29-1.55 3.3-1.23 3.3-1.23.66 1.66.24 2.88.12 3.18.77.84 1.24 1.91 1.24 3.22 0 4.61-2.81 5.63-5.49 5.93.43.37.81 1.1.81 2.22v3.29c0 .32.22.7.83.58A12 12 0 0 0 12 .5Z"/></svg> GitHub ile giriş yap</button><button class="yahoo-button" id="yahoo"><svg viewBox="0 0 32 28" aria-hidden="true" focusable="false"><path fill="currentColor" d="M1 5h6l4 10 5-10h6L11 28H5l3-7L1 5Zm25-5h6l-5 18h-5L26 0Zm-6 21h6l-1 6h-6l1-6Z"/></svg> Yahoo ile giriş yap</button><button class="primary" id="guest">Misafir olarak devam et</button><p class="login-account-note">Google, GitHub ve Yahoo girişleri farklı oyun hesapları olabilir. Mevcut ilerlemen için daha önce kullandığın yöntemle devam et; hesaplar otomatik birleştirilmez.</p><button class="text-link" id="login-legal">Kullanım Koşulları ve Gizlilik Politikası</button><p id="login-error" role="status"></p></section></div>`;
 let signingIn=false;const close=()=>{if(!signingIn)document.querySelector('#modal-root').innerHTML='';};document.querySelector('#close-login').onclick=close;document.querySelector('#login-legal').onclick=()=>showLegal(false,true);document.querySelector('#guest').onclick=()=>{if(!profile){profile={name:'Misafir oyuncu',guest:true};save('blokko-profile',profile);}close();render();activateAccountServices();consumeRoute();};
 for(const provider of ['google','github','yahoo'])document.getElementById(provider).onclick=async()=>{if(signingIn)return;signingIn=true;const controls=[...document.querySelectorAll('#modal-root button')],error=document.getElementById('login-error');controls.forEach(button=>button.disabled=true);error.textContent=({google:'Google',github:'GitHub',yahoo:'Yahoo'}[provider])+' hesabı bekleniyor…';try{const user=await login(provider);resetAccess();await checkAccess(true);profile=sessionProfile(user,provider+'.com');save('blokko-profile',profile);switchAccount(profile.uid);signingIn=false;close();render();if(!hasConsent())showLegal(true);else{activateAccountServices();consumeRoute();}}catch(e){if(error.isConnected)error.textContent=e.message;}finally{signingIn=false;controls.forEach(button=>{if(button.isConnected)button.disabled=false;});}};
}

let toastTimeout;function toast(text){const el=document.querySelector('#toast');if(!el)return;el.textContent=text;el.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('visible'),3500);}
let audio;function beep(){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();Promise.resolve(audio.resume()).catch(()=>{});const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=660;g.gain.setValueAtTime(.04,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);o.start();o.stop(audio.currentTime+.12);}catch{}}


let cloudSend=0;
async function sendActivity(){if(!hasConsent()||!profile||profile.guest)return;const uid=profile.uid;try{await submitScore(0,'word');if(profile?.uid===uid)toast('Alıştırman Topluluk’a kaydedildi.');}catch{if(profile?.uid===uid)toast('Topluluk kaydı onaylanamadı. Kupa ve ilerlemen cihazda korunuyor.');}}


function hasConsent(){return !profile||profile.guest||read('blokko-consent-'+(profile.uid||profile.name),null)?.version===LEGAL_VERSION;}
function showLegal(required=false,returnToLogin=false){
 if(required&&hasConsent())return;
 puzzleController?.pause();
 document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal legal-modal" role="dialog" aria-modal="true" aria-label="Koşullar ve gizlilik"><div class="eyebrow">ŞEFFAF VE GÜVENLİ BİR BAŞLANGIÇ</div><h2>Oyuna geçmeden önce</h2><p>Koşulları ve verilerinin nasıl kullanıldığını incele.</p><div class="legal-scroll" tabindex="0"><details open><summary>Kullanım Koşulları</summary>${terms}</details><details><summary>Gizlilik Politikası</summary>${privacy}</details></div>${required?`<label class="legal-check"><input type="checkbox" id="accept-terms"> Kullanım Koşulları’nı kabul ediyorum.</label><label class="legal-check"><input type="checkbox" id="read-privacy"> Gizlilik Politikası’nı okudum ve bilgilendirildim.</label><button class="primary" id="accept-legal" disabled>Kabul et ve devam et</button><button class="text-link" id="decline-legal">Kabul etmiyorum · Çıkış yap</button><p id="legal-error" role="status"></p>`:'<button class="primary" id="close-legal">Kapat</button>'}</section></div>`;
 const root=document.querySelector('#modal-root');
 if(!required){document.querySelector('#close-legal').onclick=()=>{root.innerHTML='';if(returnToLogin)showLogin();};return;}
 const accept=document.querySelector('#accept-legal');
 const update=()=>accept.disabled=!(document.querySelector('#accept-terms').checked&&document.querySelector('#read-privacy').checked);
 document.querySelector('#accept-terms').onchange=update;document.querySelector('#read-privacy').onchange=update;
 accept.onclick=()=>{if(accept.disabled)return;save('blokko-consent-'+(profile.uid||profile.name),{version:LEGAL_VERSION,at:Date.now()});root.innerHTML='';render();activateAccountServices();consumeRoute();};
 document.querySelector('#decline-legal').onclick=async()=>{try{await disconnectNotifications();servicesUid=null;await logout();resetAccess();profile=null;save('blokko-profile',null);switchAccount(null);render();showLogin();}catch{document.querySelector('#legal-error').textContent='Çıkış yapılamadı. Lütfen yeniden dene.';}};
}
function shopPage(){wallet=cleanWallet(read('seyyah-wallet',{}));document.querySelector('#page').innerHTML=`<section class="page-title"><div class="eyebrow">YOLCULUĞUNA KÜÇÜK BİR DESTEK</div><h1>Seyyahın çantası</h1><p>Takıldığında bir harf, bazen bütün yolu aydınlatır.</p></section>${premiumCard({profile,active:hasPremium(),expiry:premiumRecord()?.expiresAt})}<div class="wallet-card">${icon('coins')}<span>ALTIN BAKİYEN<strong>${wallet.gold}</strong></span><small>${wallet.hints} hazır ipucu<br>İlk tamamlamada: kelime başına 5 + 25 altın</small></div><div class="store-grid word-store">${HINT_PACKS.map(p=>`<article class="store-card"><span class="store-icon">${icon('lightbulb')}</span><span class="store-level">${p.hints} harf ipucu</span><h3>${p.name}</h3><p>Bulmacada istediğin zaman kullanabileceğin ${p.hints} harf açma hakkı.</p><button class="primary" data-buy="${p.id}" ${wallet.gold<p.cost?'disabled':''}>${p.cost} altın · Çantama ekle</button><small>${wallet.gold<p.cost?(p.cost-wallet.gold)+' altın daha gerekiyor':'İpuçları kullanana kadar saklanır'}</small></article>`).join('')}</div><section class="how-card">${icon('book-open')}<div><h3>Her keşif bir ödül.</h3><p>Bir aşamayı ilk kez tamamladığında hedef kelime başına 5 ve tamamlama için 25 altın kazanırsın. Tekrar oynama bölüm altınını yenilemez. Keşif defterindeki görev ödülleri ayrıca altın ve ipucu verir. Hazır ipucun yoksa oyun içinde 20 altınla bir harf açabilirsin.</p></div></section><p class="stage-note">Altın ve normal ipucu paketleri gerçek parayla satılmaz; Premium isteğe bağlı yıllık ücretli hizmettir. Eski Blokko altının korunur; satın alınmış silah geliştirmelerinin bedeli bir defaya mahsus altına dönüştürülür. Hesabınla cüzdan da oyun kaydına dahil edilir. Bağlantı kesilince normal oyun devam eder; son ilerleme cihazda korunur. Profil’den eşitleme durumunu kontrol et.</p>`;
 document.querySelector('#premium-login')?.addEventListener('click',showLogin);document.querySelector('#premium-refresh').onclick=async()=>{await checkAccess(true);if(page==='shop')render();};document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const pack=HINT_PACKS.find(p=>p.id===b.dataset.buy);document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="İpucu satın al"><h2>${pack.name}</h2><p>${pack.hints} ipucu için ${pack.cost} altın harcansın mı?</p><button class="primary" id="confirm-buy">${pack.cost} altın · Onayla</button><button class="text-link" id="cancel-buy">Vazgeç</button></section></div>`;document.querySelector('#cancel-buy').onclick=()=>document.querySelector('#modal-root').innerHTML='';document.querySelector('#confirm-buy').onclick=e=>{if(!canPlay()||rewardBusy||accountView.kind==='loading'){toast('Çevrimiçi hesap kontrolünü bekle.');return;}e.currentTarget.disabled=true;const result=buyHints(read('seyyah-wallet',{}),pack.id);if(result.ok){wallet=result.wallet;save('seyyah-wallet',wallet);}render();toast(result.ok?'İpuçların çantanda!':'Yeterli altının yok.');};});refresh();}
async function openUpdate(){if(updateState.status!=='update')return;try{if(Capacitor.isNativePlatform())await Browser.open({url:updateState.url});else window.open(updateState.url,'_blank','noopener,noreferrer');}catch{toast('İndirme sayfası açılamadı. İnternet bağlantını kontrol et.');}}
function offerUpdate(){if(updateState.status!=='update')return;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Güncelleme"><h2>Yeni sürüm hazır!</h2><p>${escape(updateState.message)} Mevcut sürümün ${APP_VERSION}. APK’yı GitHub’dan indirip güncelleyebilirsin.</p><button class="primary" id="download-update">GitHub’da aç</button><button class="text-link" id="skip-update">Şimdi değil · Devam et</button></section></div>`;document.querySelector('#download-update').onclick=openUpdate;document.querySelector('#skip-update').onclick=()=>{document.querySelector('#modal-root').innerHTML='';afterBoot();};}
function afterBoot(){if(!profile)showLogin();else if(!hasConsent())showLegal(true);else{activateAccountServices();consumeRoute();}}
async function boot(){
 const notificationInit=initNotifications(route=>{queuedRoute=route;consumeRoute();},n=>toast(n.body)).catch(()=>{});
 document.querySelector('#app').innerHTML=`<section class="boot-screen" role="status" aria-live="polite"><div class="boot-mark"><span></span><span></span><span></span><span></span></div><h1>Kelime<br><span>Seyyahı</span></h1><p>Yolculuğun hazırlanıyor…</p><div class="boot-loader"></div><small>GitHub üzerinden sürüm kontrol ediliyor</small><small>v${APP_VERSION}</small></section>`;
 const [update,session]=await Promise.all([checkUpdate(),configured&&profile&&!profile.guest?getSessionUser().then(user=>({user,ok:true})).catch(()=>({ok:false})):Promise.resolve({ok:false}),new Promise(r=>setTimeout(r,700))]);
 updateState=update;
 if(session.ok){profile=session.user?sessionProfile(session.user,profile?.uid===session.user.uid?profile?.provider:undefined):null;save('blokko-profile',profile);}
 switchAccount(profile&&!profile.guest?profile.uid:null);await notificationInit;if((!profile||profile.guest)&&pushEnabled())await disconnectNotifications();render();bootReady=true;refreshAccessUI();if(updateState.status==='update')offerUpdate();else{afterBoot();if(updateState.status==='unknown')toast(updateState.message);}
}
function streakCard(action=true){const s=currentStreak();return `<section class="streak-card"><span class="streak-icon">${icon('flame')}</span><div><span class="eyebrow">GÜNLÜK SERİN</span><h2>${s.streak} gün <small>· En uzun ${s.best} gün</small></h2><p>${s.count?`Bugün ${s.count} alıştırma tamamladın. Harika gidiyorsun!`:'Bugün bir bulmaca tamamla, serini sürdür.'}</p><small>İstanbul saati · ${profile&&!profile.guest?'Hesabının oyun kaydına dahil':'Bu cihazdaki misafire özel seri'}</small></div>${action?'<button class="primary" id="streak-practice">Yap →</button>':''}</section>`;}
function notificationSettings(){const native=nativeNotificationsSupported();return `<section class="notification-settings"><div class="section-heading"><h2>${icon('bell')} Hatırlatmalar</h2></div><label class="notification-option"><span><b>Alıştırma zamanı</b><small>3 saatte bir, gece dahil. Bildirimdeki “Yap” ile devam et.</small></span><input type="checkbox" id="practice-reminders" ${remindersEnabled()?'checked':''} ${!native||notificationBusy?'disabled':''}></label><label class="notification-option"><span><b>Duyurular ve Bayram Bereketi</b><small>GitHub’dan yayımlanan haberler için telefon bildirimi.</small></span><input type="checkbox" id="event-notifications" ${eventNotificationsEnabled()?'checked':''} ${!native?'disabled':''}></label><div class="notification-option"><span><b>Beğeniler · Ücretsiz</b><small>Topluluk ekranındaki “Sana gelen alkışlar” bölümünde görünür. Bu ekran açıkken yeni beğeniler güncellenir. Uygulama kapalıyken telefon bildirimi gönderilmez.</small></span></div><p class="stage-note">${native?'İlk açışta bildirim izni istenir. Android pil tasarrufu ve telefon ayarları hatırlatmaları geciktirebilir. Hatırlatmalar cihaz saatine göredir.':'Sistem bildirimleri Android uygulamasında kullanılabilir.'} Beğeniler için Google, GitHub veya Yahoo girişi ve internet gerekir. Blaze veya Cloud Functions gerekmez. Spark kullanım kotaları geçerlidir. Alıştırma hatırlatmalarını buradan kapatabilirsin.</p><p id="notification-error" role="status"></p></section>`;}
function bindNotificationSettings(){for(const [id,set] of [['practice-reminders',setReminders],['event-notifications',setEventNotifications]]){const input=document.getElementById(id);input.onchange=async()=>{if(notificationBusy)return;if(!hasConsent()){input.checked=false;showLegal(true);return;}const enabled=input.checked;notificationBusy=true;syncNotificationControls();input.disabled=true;const el=document.getElementById('notification-error');el.textContent='Bildirim ayarı güncelleniyor…';try{await set(enabled);if(el.isConnected)el.textContent=enabled?(id==='event-notifications'?'Duyuru ve bayram bildirimleri açık.':'Hatırlatmalar açık. İlk hatırlatma yaklaşık 3 saat sonra.'): 'Bildirim tercihin kapatıldı.';}catch(e){if(el.isConnected)el.textContent=e.code==='permission-denied'?'Yeni Firestore kuralları yayınlanmalı. Bildirim kaydı tamamlanamadı.':e.message;input.checked=id==='event-notifications'?eventNotificationsEnabled():remindersEnabled();}finally{notificationBusy=false;syncNotificationControls();}};}}
function syncNotificationControls(){const events=document.getElementById('event-notifications');if(events){events.disabled=!nativeNotificationsSupported()||notificationBusy;events.checked=eventNotificationsEnabled();}const r=document.getElementById('practice-reminders');if(r){r.disabled=!nativeNotificationsSupported()||notificationBusy;r.checked=remindersEnabled();}}
function consumeRoute(){if(!bootReady||accountView.kind==='loading'||!queuedRoute||!profile||!hasConsent()||document.querySelector('#modal-root')?.children.length)return;const route=queuedRoute;queuedRoute=null;page=route==='news'?'news':route==='community'?'community':'home';render();if(route==='practice')play(stage);window.scrollTo(0,0);}
function activateAccountServices(){if(!canUseServices())return;if(!trophyNoticeSeen()){showTrophyNotice();return;}if(!profile||profile.guest||!hasConsent()||servicesUid===profile.uid)return;servicesUid=profile.uid;syncAccountNow();if(pushEnabled())disconnectNotifications().catch(()=>{});}

let accountView={kind:'local',message:'Hesap kaydı bekleniyor.'},accountTimer;
function captureAccount(){return cleanAccount({stage:read('seyyah-stage',1),wallet:read('seyyah-wallet',{}),progress:read('seyyah-progress',{}),records:[],streak:read(streakKey(),{}),trophies:read('seyyah-trophies',{}),avatar:read('seyyah-avatar',{}),journey:read('seyyah-journey',{}),cosmeticsPremium:read('seyyah-premium-cosmetics',false)});}
function applyAccount(data){stage=data.stage;wallet=cleanWallet(data.wallet);progress=data.progress;records=[];trophies=cleanTrophies(data.trophies);avatar=cleanAvatar(data.avatar);journey=cleanJourney(data.journey);for(const [key,value] of Object.entries({'seyyah-stage':stage,'seyyah-wallet':wallet,'seyyah-progress':progress,'seyyah-records':[],'seyyah-trophies':trophies,'seyyah-avatar':avatar,'seyyah-journey':journey,'seyyah-premium-cosmetics':data.cosmeticsPremium===true,[streakKey()]:data.streak}))localStorage.setItem(key,JSON.stringify(value));if(document.querySelector('#page')&&!puzzleController&&!document.querySelector('#modal-root')?.children.length)render();}
const accountSync=createAccountSync({storage:localStorage,load:loadAccount,commit:commitAccount,apply:applyAccount,status:value=>{accountView=value;updateAccountStatus();if(value.kind!=='loading')queueMicrotask(consumeRoute);}});
function switchAccount(uid){if(accountSync.state&&accountSync.uid===uid)return;clearTimeout(accountTimer);bonusUnconfirmed=false;cloudSend++;localStorage.removeItem('seyyah-cloud-status');accountSync.bind(uid);}
function accountPanel(){return `<section class="notification-settings"><h2>Hesap bulut kaydı</h2><p id="account-detail" role="status"></p><div id="account-controls"></div><p class="stage-note">Aşama, bulmaca ilerlemesi, altın, ipuçları, günlük seri, kupa, prestij, avatar ve keşif defteri eşitlenir. Eski puanlar sıfırlandı ve yeni sıralamada kullanılmaz. İki cihazda aynı anda oynarsan farklı kayıtlar için seçim istenir. İnternetsiz değişiklikler bu cihazda bekler.</p></section>`;}
function updateAccountStatus(){const signed=profile&&!profile.guest;const banner=document.getElementById('account-sync-state');if(banner){banner.hidden=!signed;banner.textContent=accountView.message;}const detail=document.getElementById('account-detail'),controls=document.getElementById('account-controls');if(!detail||!controls)return;detail.textContent=accountView.message;controls.innerHTML=signed?`<button class="primary" id="sync-account" ${accountView.kind==='loading'?'disabled':''}>Şimdi eşitle</button>${accountView.conflict?`<p>Bu cihaz: aşama ${accountSync.state.stage} · ${trophyCount(accountSync.state.trophies)} kupa<br>Bulut: aşama ${cleanAccount(accountView.conflict.state).stage} · ${trophyCount(cleanAccount(accountView.conflict.state).trophies)} kupa</p><button class="text-link" id="use-cloud">Buluttaki kayıttan devam et</button><button class="text-link" id="use-device">Bu cihazdaki kaydı buluta aktar</button><small>Seçim öncesi cihaz kaydı ve üzerine yazılacak bulut kaydı bu cihazda yedeklenir. Seçim aşama, cüzdan ve diğer oyun verilerinin tamamını kapsar.</small>`:''}`:'<p>Bulut kaydı için Google, GitHub veya Yahoo ile giriş yap. Misafir ilerlemesi bu cihazda ayrı saklanır.</p>';document.getElementById('sync-account')?.addEventListener('click',()=>syncAccountNow());for(const [id,choice] of [['use-cloud','cloud'],['use-device','device']])document.getElementById(id)?.addEventListener('click',()=>{if(confirm(choice==='cloud'?'Bu cihazdaki ilerleme yerine buluttaki kayıt yüklensin mi? Cihaz kaydı ayrıca yedeklenecek.':'Bu cihazdaki ilerleme, buluttaki aşama ve cüzdanın yerine kaydedilsin mi?'))syncAccountNow(choice);});}
async function syncAccountNow(choice){clearTimeout(accountTimer);if(!canUseServices())return;if(!profile||profile.guest||!hasConsent())return;if(!configured){accountView={...accountView,kind:'error',message:'Bu web önizlemesinde bulut bağlantısı yapılandırılmadı. Android uygulamasında eşitleyebilirsin.'};updateAccountStatus();return;}await accountSync.sync(choice);if(!accountSync.dirty)bonusUnconfirmed=false;if(accountSync.dirty&&accountView.kind==='pending')accountTimer=setTimeout(()=>syncAccountNow(),5000);}
// Preserve legacy data once, bound only to the account already open on upgrade.
const initialUid=profile&&!profile.guest?profile.uid:null;
if(!read('seyyah-account-migrated-v1',false)){const seed=captureAccount();seed.records=seed.records.filter(r=>!r.uid||r.uid===initialUid);localStorage.setItem('seyyah-before-account-sync',JSON.stringify(seed));accountSync.bind(initialUid,seed);save('seyyah-account-migrated-v1',true);}else accountSync.bind(initialUid);
progressHook=key=>{if(['seyyah-stage','seyyah-wallet','seyyah-progress','seyyah-records','seyyah-trophies','seyyah-avatar','seyyah-journey','seyyah-premium-cosmetics',streakKey()].includes(key)){accountSync.save(captureAccount());clearTimeout(accountTimer);if(profile&&!profile.guest&&hasConsent())accountTimer=setTimeout(()=>syncAccountNow(),5000);}};
window.addEventListener('online',()=>{if(!puzzleController)syncAccountNow();});
function trophyNoticeSeen(){return read('seyyah-trophy-notice-v1-'+(profile&&!profile.guest?profile.uid:'guest'),false);}
function showTrophyNotice(){if(document.querySelector('#modal-root')?.children.length)return;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Puan sistemi değişti"><h2>Puan sistemi değişti</h2><p>Eski puanlar sıfırlandı. Artık her aşamanın yeni kupa sistemindeki ilk tamamlanması 20 kupa kazandırır. Aynı aşama tekrar kupa vermez.</p><p>Aşamaların ve altının korundu. Eski aşamalarını yeniden bitirerek kupalarını kazanabilirsin. 1000 kupa harcayarak prestijini yükseltebilirsin.</p><button class="primary" id="accept-trophies">Tamam</button></section></div>`;document.getElementById('accept-trophies').onclick=()=>{save('seyyah-trophy-notice-v1-'+(profile&&!profile.guest?profile.uid:'guest'),true);document.getElementById('modal-root').innerHTML='';activateAccountServices();consumeRoute();};}
function avatarPanel(){const labels={hair:'Saç',outfit:'Kıyafet',eyes:'Göz',face:'Yüz ifadesi',hat:'Şapka'};return `<section class="notification-settings avatar-editor" id="avatar-editor-panel"><h2>Avatarını oluştur</h2><div id="avatar-preview">${avatarSVG(avatar)}</div><div class="avatar-options">${Object.entries(AVATAR_OPTIONS).map(([key,options])=>`<label>${labels[key]}<select data-avatar="${key}">${options.map((label,i)=>`<option value="${i}" ${avatar[key]===i?'selected':''} ${avatarAvailable(key,i,journey.claimed.length,read('seyyah-premium-cosmetics',false))?'':'disabled'}>${label}${avatarAvailable(key,i,journey.claimed.length,read('seyyah-premium-cosmetics',false))?'':isPremiumAvatar(key,i)?' · Premium ile kalıcı açılır':' · '+avatarRequirement(key,i)+' görev ödülü'}</option>`).join('')}</select></label>`).join('')}</div><p class="stage-note">Seçimlerin otomatik kaydedilir. Hesabın eşitlendiğinde avatarın diğer cihazına da gelir ve kupa sıralamasında görünür.</p></section>`;}
function bindAvatar(){document.getElementById('edit-avatar')?.addEventListener('click',()=>document.getElementById('avatar-editor-panel').scrollIntoView({behavior:'smooth',block:'start'}));document.querySelectorAll('[data-avatar]').forEach(select=>select.onchange=()=>{if(!canPlay()||rewardBusy||accountView.kind==='loading'){select.value=String(avatar[select.dataset.avatar]);toast('Hesap eşitlemesini bekle.');return;}if(!avatarAvailable(select.dataset.avatar,Number(select.value),journey.claimed.length,read('seyyah-premium-cosmetics',false))){select.value=String(avatar[select.dataset.avatar]);return;}avatar=cleanAvatar({...avatar,[select.dataset.avatar]:Number(select.value)});save('seyyah-avatar',avatar);document.getElementById('avatar-preview').innerHTML=avatarSVG(avatar);const portrait=document.querySelector('.avatar-portrait');if(portrait)portrait.innerHTML=avatarSVG(avatar);});}
boot();

function showJourney(){document.getElementById('page').innerHTML=journeyPage(journey,captureAccount(),playDate());const allowed=()=>{if(!canUseServices()||rewardBusy||accountSync.busy){toast('Çevrimiçi hesap kontrolünü bekle.');return false;}if(!hasConsent()){showLegal(true);return false;}return true;};
 document.getElementById('start-journey')?.addEventListener('click',async()=>{if(!allowed())return;rewardBusy=true;refreshAccessUI();try{const day=await ensureJourneyClock();journey={...startJourney(journey,trustedDate()),start:day};save('seyyah-journey',journey);render();}catch{toast('Güvenli takvim başlatılamadı. Bağlantını ve Firestore kurallarını kontrol et.');}finally{rewardBusy=false;refreshAccessUI();}});
 document.querySelectorAll('[data-quest]').forEach(button=>button.onclick=()=>{if(!allowed())return;journey=selectQuest(journey,Number(button.dataset.quest),trustedDate());save('seyyah-journey',journey);render();document.querySelector('.active-quest')?.scrollIntoView({behavior:'smooth',block:'start'});});
 document.getElementById('claim-quest')?.addEventListener('click',async()=>{if(!allowed())return;rewardBusy=true;refreshAccessUI();const uid=liveIdentity()?.uid;try{const day=await ensureJourneyClock();journey={...journey,start:day};save('seyyah-journey',journey);if(profile&&!profile.guest){await syncAccountNow();if(accountSync.dirty||accountSync.conflict)throw Error('Önce Profil’den hesabını eşitle.');}else{const recovered=await guestRewardCheckpoint(captureAccount());if(recovered){if(liveIdentity()?.uid!==uid)throw Error('Hesap değişti.');if(!confirm('Ödül sunucuda zaten alınmış. Cihaz kaydını yedekleyip sunucudaki kaydı geri yükleyelim mi?'))return;localStorage.setItem('seyyah-guest-before-reward-recovery',JSON.stringify(captureAccount()));applyAccount(recovered.state);accountSync.save(captureAccount());render();return;}}const result=await claimSecureQuest(journey.active);if(liveIdentity()?.uid!==uid)throw Error('Hesap değişti.');if(profile&&!profile.guest)accountSync.acceptRemote(profile.uid,result.data);else{applyAccount(result.data.state);accountSync.save(captureAccount());}render();toast('Görev ödülü sunucuda doğrulandı.');}catch(e){toast(e.code==='permission-denied'?'Ödül sunucuda onaylanmadı. Görev günü, bağlantı veya yönetici kurulumu kontrol edilmeli.':e.message||'Ödül alınamadı. Tekrar dene.');}finally{rewardBusy=false;refreshAccessUI();}});

 document.getElementById('quest-play')?.addEventListener('click',()=>play(stage));document.getElementById('journey-home').onclick=()=>{page='home';render();window.scrollTo(0,0);};
}

let calendarDay=dayKey();
function refreshCalendar(){const today=dayKey();if(today!==calendarDay){calendarDay=today;if(page==='journey'&&!puzzleController&&!document.querySelector('#modal-root')?.children.length)render();}}
setInterval(refreshCalendar,60000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshCalendar();});

function refreshAccessUI(){if(!bootReady)return;if(profile&&!profile.guest&&profile.uid===liveIdentity()?.uid&&premiumCosmetics()&&!read('seyyah-premium-cosmetics',false))save('seyyah-premium-cosmetics',true);const access=accessStatus(),status=access==='ready'&&rewardBusy?'processing':access;showAccessOverlay(status,livePolicy(),()=>checkAccess(true),maintenanceCode,async()=>{try{await logout();}catch{}profile=null;save('blokko-profile',null);switchAccount(null);resetAccess();render();showLogin();});if(status!=='ready')puzzleController?.pause();else{activateAccountServices();if(page==='home'){const button=document.getElementById('open-news');if(button){const replacement=document.createElement('div');replacement.innerHTML=newsBanner(livePolicy(),serverClock.now());button.replaceWith(replacement.firstElementChild);document.getElementById('open-news').onclick=()=>{page='news';render();};}}notifyLiveContent();}}
let notificationPromptOpen=false;
function notifyLiveContent(){if(!canUseServices()||!bootReady||document.getElementById('modal-root')?.children.length)return;const notices=activeAnnouncements(livePolicy(),serverClock.now()),first=notices.find(a=>!read('seyyah-announcement-'+a.id,false));if(first){const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><span class="eyebrow">SEYYAH POSTASI</span><h2>${escape(first.title)}</h2><p>${escape(first.body)}</p><button class="primary" id="read-notice">Tamam</button><button class="text-link" id="view-notices">Tüm duyurular</button></section></div>`;const close=()=>{save('seyyah-announcement-'+first.id,true);root.innerHTML='';};document.getElementById('read-notice').onclick=close;document.getElementById('view-notices').onclick=()=>{close();page='news';render();};return;}
 restoreEventNotifications().catch(()=>{});promptEventNotifications();
}
onAccessChange(refreshAccessUI);startAccess();

function promptEventNotifications(){if(!nativeNotificationsSupported()||read('event-permission-asked',false)||notificationPromptOpen)return;notificationPromptOpen=true;const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><h2>Yolculuktan haberdar ol</h2><p>Bayram Bereketi ve yeni duyurular için bildirim almak ister misin? İzin vermesen de oynayabilirsin.</p><button class="primary" id="allow-event-push">İzin ver</button><button class="text-link" id="skip-event-push">Şimdi değil</button><p id="event-permission-error" role="status"></p></section></div>`;const close=()=>{save('event-permission-asked',true);notificationPromptOpen=false;root.innerHTML='';};document.getElementById('skip-event-push').onclick=close;document.getElementById('allow-event-push').onclick=async e=>{e.currentTarget.disabled=true;try{await setEventNotifications(true);close();}catch(error){save('event-permission-asked',true);document.getElementById('event-permission-error').textContent=error.message;}};}
